let KEY='yoyu-ledger-data-v1';let real=fresh(),corrupt=false,storageOK=true;try{const raw=localStorage.getItem(KEY);if(raw)real=validateBackup(JSON.parse(raw))}catch{corrupt=true}let demo=false,state=real=upgrade(real),page='home',month=today().slice(0,7),privateMode=false,apiKey='',model='auto',pendingImage=null,drafts=[],aiBusy=false,recognition=null;let filters={q:'',type:'',account:''};let entry=null,entryMode='manual',aiMode='text';let activeBook='personal',advanced,cloud,invoices,settlements,daily,investments;let toastTimer,aiGeneration=0,aiRequest=null,router=null,autoSwitch=true,modelLoading=false,modelError='',lastModel='';
