const accountName=id=>state.accounts.find(a=>a.id===id)?.name||'未指定';const accountIcon=a=>(a.kind==='card'||a.kind==='bnpl')?'card':a.kind==='bank'?'bank':a.kind==='mobile'?'phone':'wallet';const catIcon=c=>({'餐飲':'food','交通':'bus','購物':'bag','生活':'home','娛樂':'play','健康':'health','居住':'home','學習':'book','手續費／利息':'card','其他':'wallet'}[c]);
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function persist(){if(demo)return true;if(corrupt){toast('原有資料無法讀取，請先到設定下載原始資料或還原備份');return false}try{localStorage.setItem(KEY,JSON.stringify(state));real=state;storageOK=true;return true}catch{storageOK=false;toast('儲存空間不足或被封鎖，請立即下載備份');return false}}
function commit(next){const old=state;try{state=upgrade(validateBackup(next))}catch(e){toast(e.message);return false}if(!persist()){state=old;return false}advanced?.onChange(structuredClone(state));cloud?.onChange();return true}
function summary(s,m){const out=baseSummary(s,m,{bookId:activeBook==='all'?null:activeBook,cycleDay:s.features?.cycleDay||1});if(activeBook!=='all')out.budget=s.features?.bookBudgets[activeBook+':'+m]??out.budget;return out}

function navButton(id,label,icon){return `<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${I(icon)}<span>${label}</span></button>`}
function monthUI(){return `<div class="month-control"><button class="icon-btn" data-month="-1" aria-label="上一個月">${I('left')}</button><input type="month" aria-label="選擇月份" id="month" value="${month}"><button class="icon-btn" data-month="1" aria-label="下一個月">${I('right')}</button></div>`}
function amountHTML(n,cls=''){const [prefix,...r]=money(n).split('$');return `<span class="sensitive ${cls}"><small>NT$</small>${r.join('$')}</span>`}
function heading(title,sub,extra=''){return `<div class="page-title"><div><div class="eyebrow">YOUR EVERYDAY, A LITTLE LIGHTER</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="controls">${extra}</div></div>`}
function render(){if(activeBook!=='all'&&!state.features.books.some(b=>b.id===activeBook))activeBook='personal';const pageNames={home:'收支總覽',ledger:'我的帳本',reports:'收支報表',accounts:'帳戶管理',settings:'偏好設定',stocks:'股票投資',invoices:'發票紀錄',settlements:'代墊／分帳',available:'可花金額',bills:'待繳／固定收支',plans:'分期管理',cashflow:'現金流',reconcile:'帳戶對帳',budgets:'預算與帳本'};$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><img src="./icon.svg" alt=""><div><strong>日常有餘</strong><small>MAKE ROOM FOR LIFE</small></div></div><nav class="nav" aria-label="主要導覽">${navButton('home','收支總覽','grid')}${navButton('stocks','股票投資','chart')}${navButton('ledger','我的帳本','book')}${navButton('reports','收支報表','chart')}${navButton('accounts','帳戶管理','wallet')}${navButton('bills','待繳帳單','book')}${navButton('plans','分期管理','card')}${navButton('cashflow','現金流預估','chart')}${navButton('reconcile','帳戶對帳','check')}${navButton('budgets','預算與帳本','wallet')}${navButton('invoices','發票紀錄','book')}${navButton('settlements','代墊／分帳','wallet')}${navButton('available','可花金額','leaf')}${navButton('settings','偏好設定','settings')}</nav><div class="sidebar-note">${I('leaf')}<br>一筆一筆記下日常，<br>為喜歡的生活留點餘裕。</div><div class="profile"><span class="avatar">餘</span><div>我的日常帳本<br><small id="cloud-profile">${cloud?.hasUser()?'帳號帳本 · 支援離線':'訪客帳本 · 此裝置'}</small></div></div></aside><main class="main ${page==='home'?'home-page '+(daily.prefs().compact?'daily-compact':''):''} ${privateMode?'hide-amount':''}"><header class="topbar"><span class="crumb">我的空間 <span style="margin:0 8px;color:#bac1b5">/</span> ${pageNames[page]}</span><div class="top-actions">${installUI.button()}<span class="pill"><span class="dot"></span><span id="cloud-pill">${navigator.onLine?(cloud?.label()||'本機儲存'):'離線使用中'}</span></span><button class="icon-btn privacy-toggle" id="privacy" aria-label="${privateMode?'顯示':'隱藏'}金額" aria-pressed="${privateMode}">${I('eye')}</button><button class="icon-btn" data-page="settings" aria-label="開啟設定">${I('settings')}</button></div></header>${demo?`<div class="demo-banner"><span>示範模式 · 這些數字是範例，修改不影響你的帳目</span><button id="exit-demo">回到我的帳本 ${I('arrow')}</button></div>`:''}${corrupt?'<div class="notice error">原有資料暫時無法讀取，已停止寫入以保護資料。請到設定下載原始資料，或還原有效備份。</div>':''}${!storageOK?'<div class="notice error">資料尚未成功存檔，請立即匯出備份。</div>':''}<section id="content">${page==='stocks'?'':advanced.toolbar()}${({home:home,ledger:ledger,reports:reports,accounts:accounts,settings:settings,stocks:investments.page,invoices:invoices.page,settlements:settlements.page,available:settlements.availablePage,...advanced.pages}[page])()}</section><footer class="footer"><span>日常有餘 · 留住日常，留點餘裕</span><span>離線記帳 · 可選雲端同步 · 加密備份</span></footer></main><nav class="mobile-nav" aria-label="手機導覽">${navButton('home','總覽','grid')}${navButton('ledger','帳本','book')}<button class="add" data-new="" aria-label="新增記帳">${I('plus')}</button>${navButton('reports','報表','chart')}${navButton('accounts','帳戶','wallet')}</nav>`;bind();}
function home(){const full=fullHome();if(!daily.prefs().compact)return full;const recent=state.transactions.filter(t=>inPeriod(t.date,month,state.features.cycleDay)&&(activeBook==='all'||(t.bookId||'personal')===activeBook)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3);return `<div class="compact-only">${daily.mobileHome({summary:summary(state,month),recentHTML:txList(recent),availableHTML:settlements.homePanel(),investmentHTML:investments.homePanel()})}</div><div class="full-only">${full}</div>`}
function fullHome(){const s=summary(state,month),ratio=s.budget?Math.round(s.expense/s.budget*100):s.expense>0?100:0;const previous=new Date(month+'-15T12:00:00Z');previous.setUTCMonth(previous.getUTCMonth()-1);const prev=summary(state,previous.toISOString().slice(0,7));const diff=prev.expense>0?((s.expense-prev.expense)/prev.expense*100).toFixed(0):null;return heading('讓生活，多一點餘裕。','每一筆小記錄，都是更了解自己的開始。',monthUI()+`<button class="primary" data-new="">${I('plus')}記一筆</button>`)+investments.homePanel()+daily.templatePanel()+daily.reminder()+settlements.homePanel()+advanced.homePanel()+`<div class="overview"><div class="card hero-card"><div class="card-label">本月支出 <span style="font-size:10px;letter-spacing:1px">MONTHLY SPENDING</span></div><div class="large-amount sensitive"><span>NT$</span>${money(s.expense).slice(3)}</div><div class="hero-bottom">${I('chart')} ${diff===null?'慢慢累積，讓花費變得清楚':`較上月${Number(diff)>0?'增加':'減少'} ${Math.abs(Number(diff))}% · 含本月退款`}</div></div><div class="card"><div class="card-label">本月收入<span class="metric-icon">${I('down')}</span></div><div class="metric-value">${amountHTML(s.income)}</div><p class="metric-note">每一份努力，都值得記錄</p><div class="metric-foot">${I('check')} 依入帳日期統計</div></div><div class="card"><div class="card-label">本月結餘<span class="metric-icon">${I('wallet')}</span></div><div class="metric-value">${amountHTML(s.net)}</div><p class="metric-note">收入扣除支出後的餘額</p><div class="metric-foot">${I('leaf')} 不是帳戶可用餘額</div></div></div><div class="content-grid"><div class="left-col"><div class="card"><div class="card-heading"><h2>隨手記一筆</h2><small>熟悉的日常，一點就好</small></div><div class="quick-grid">${[['午餐','餐飲','food'],['咖啡','餐飲','coffee'],['交通','交通','bus'],['購物','購物','bag']].map(([name,c,icon])=>`<button class="quick" data-quick="${name}" data-cat="${c}"><span class="bubble">${I(icon)}</span>${name}</button>`).join('')}</div></div><div class="card"><div class="card-heading"><h2>近期紀錄 <small style="margin-left:6px">RECENT</small></h2><button class="text-btn" data-page="ledger">查看全部 ${I('right')}</button></div>${txList(state.transactions.filter(t=>inPeriod(t.date,month,state.features.cycleDay)&&(activeBook==='all'||(t.bookId||'personal')===activeBook)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5))}</div><div class="card"><div class="card-heading"><h2>我的帳戶</h2><button class="text-btn" data-page="accounts">管理 ${I('right')}</button></div>${state.accounts.map(a=>`<div class="account-list-row"><span class="metric-icon">${I(accountIcon(a))}</span><span class="name">${E(a.name)}${isLinked(a)?`<small class="tx-meta" style="display:block">綁定 ${E(accountName(a.linkedAccount))}</small>`:''}</span><strong class="sensitive">${accountAmount(a)}</strong></div>`).join('')}</div></div><div class="right-col"><div class="card budget-card"><div class="card-heading"><h2>本月預算</h2><button class="text-btn" id="edit-budget">調整 ${I('edit')}</button></div><div class="section-caption">${s.budget-s.expense>=0?'還可以花':'已超出預算'}</div><div class="budget-main sensitive ${s.budget-s.expense<0?'overspent':''}"><strong>${money(Math.abs(s.budget-s.expense))}</strong></div><div class="progress" role="progressbar" aria-label="已用預算" aria-valuenow="${Math.max(0,Math.min(100,ratio))}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.max(0,Math.min(100,ratio))}%;${ratio>100?'background:var(--danger)':''}"></span></div><div class="budget-detail"><span>${s.budget?`已用 ${ratio}%`:s.expense>0?'預算為 0 · 已超支':'預算為 0'}</span><span class="sensitive">預算 ${money(s.budget)}</span></div></div><div class="card ai-card"><div class="ai-tag">${I('spark')} SMART LITTLE HELPER</div><h3>一句話，就記好了。</h3><p>把今天的花費告訴我，<br>剩下的，讓小幫手整理。</p><form id="quick-ai" class="ai-input"><input id="quick-text" aria-label="一句話記帳" placeholder="午餐150現金，咖啡120刷卡" maxlength="1000"><button aria-label="解析記帳內容">${I('arrow')}</button></form><div class="ai-links"><button id="home-mic">${I('mic')}語音輸入</button><button id="home-photo">${I('camera')}拍照辨識</button></div><div class="help" style="font-size:10px;margin-bottom:0">${apiKey?'Gemini AI 已連接 · 送出後先預覽':'免金鑰文字解析可直接用 · AI 可在設定啟用'}</div></div><div class="card"><div class="card-heading"><h2>錢都花在哪裡？</h2><small>本月分類</small></div>${categoryBars(s)}</div></div></div>${!demo&&!state.transactions.length?`<div class="notice" style="margin-top:20px">歡迎來到你的新帳本。先設定帳戶期初餘額，再記下第一筆。<button class="text-btn" id="try-demo" style="margin-left:10px">先逛逛示範帳本 ${I('arrow')}</button></div>`:''}`}
function txList(txs){if(!txs.length)return `<div class="empty">${I('book')}<br>這裡還很清爽。<br>記下第一筆，開始看見生活的流向。<br><button class="text-btn" data-new="">${I('plus')}記一筆</button></div>`;return `<div class="tx-list">${txs.map((t,i)=>`<div class="tx-row"><span class="tx-icon c${i%4}">${I(t.type==='transfer'?'refresh':t.type==='income'?'down':catIcon(t.category))}</span><div class="tx-body"><div class="tx-name">${E(t.note)}</div><div class="tx-meta">${E(t.date.slice(5).replace('-','/'))} · ${E(t.type==='transfer'?accountName(t.account)+' → '+accountName(t.toAccount):t.category+' · '+accountName(t.account))}</div></div><div class="tx-value ${t.type} sensitive">${t.type==='expense'?'−':t.type==='transfer'?'': '+'}${money(t.amount).slice(3)}<small>${TYPE_LABEL[t.type]}</small></div><button class="tx-edit" data-edit="${E(t.id)}" aria-label="編輯${E(t.note)}">${I('edit')}</button></div>`).join('')}</div>`}
function categoryBars(s){const entries=Object.entries(s.categories).filter(([,n])=>n!==0).sort((a,b)=>b[1]-a[1]);if(!entries.length)return '<div class="empty">分類圖表會隨著記帳慢慢長出來。</div>';const total=entries.reduce((a,[,n])=>a+Math.max(0,n),0);return entries.map(([c,n],i)=>`<div class="category-row"><div class="category-line"><span>${E(c)} <small>${total&&n>0?Math.round(n/total*100)+'%':n<0?'淨退款':''}</small></span><span class="sensitive">${money(n)}</span></div><div class="mini-progress"><span style="width:${total?Math.max(0,n/total*100):0}%;background:${['#577d62','#8fa887','#b1bf98','#b8a58b','#b1b9bb'][i%5]}"></span></div></div>`).join('')}
function ledger(){let tx=state.transactions.filter(t=>inPeriod(t.date,month,state.features.cycleDay)&&(activeBook==='all'||(t.bookId||'personal')===activeBook)&&(!filters.type||t.type===filters.type)&&(!filters.account||t.account===filters.account||t.toAccount===filters.account||fundingAccount(state,t.account)===filters.account||(t.type==='transfer'&&fundingAccount(state,t.toAccount)===filters.account))&&(!filters.q||(t.note+' '+t.category+' '+accountName(t.account)+' '+(t.tags||[]).join(' ')).toLowerCase().includes(filters.q.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));return heading('我的帳本','一筆一筆，拼出你的生活模樣。',monthUI()+`<button class="primary" data-new="">${I('plus')}記一筆</button>`)+`<div class="filters"><label class="search">${I('search')}<input id="search" aria-label="搜尋紀錄" placeholder="搜尋項目、分類或帳戶" value="${E(filters.q)}"></label><select id="filter-type" aria-label="篩選類型"><option value="">全部類型</option>${Object.entries(TYPE_LABEL).map(([v,l])=>`<option value="${v}" ${filters.type===v?'selected':''}>${l}</option>`).join('')}</select><select id="filter-account" aria-label="篩選帳戶"><option value="">全部帳戶</option>${state.accounts.map(a=>`<option value="${E(a.id)}" ${filters.account===a.id?'selected':''}>${E(a.name)}</option>`).join('')}</select><button class="secondary" id="export-csv">${I('download')}匯出 CSV</button></div><div class="card"><div class="card-heading"><h2>交易紀錄</h2><small>共 ${tx.length} 筆 · 轉帳不計入收支</small></div>${txList(tx)}</div>`}
function reports(){const s=summary(state,month);const series=Array.from({length:6},(_,i)=>{const d=new Date(month+'-15T12:00:00Z');d.setUTCMonth(d.getUTCMonth()-(5-i));const m=d.toISOString().slice(0,7);return {m,n:summary(state,m).expense}});const max=Math.max(1,...series.map(x=>x.n));return heading('看見花費，也看見生活。','了解錢的流向，下一步就更有方向。',monthUI())+`<div class="stat-grid">${[['本月收入',s.income,'每份努力的累積'],['本月支出',s.expense,'已扣除本月退款'],['本月結餘',s.net,'收入 − 支出']].map(([l,n,d])=>`<div class="card"><div class="card-label">${l}</div><div class="metric-value">${amountHTML(n)}</div><p class="metric-note">${d}</p></div>`).join('')}</div><div class="report-grid"><div class="card"><div class="card-heading"><h2>近六個月支出</h2><small>單位：新台幣</small></div><div class="chart-wrap" role="img" aria-label="${E(series.map(x=>x.m+'支出'+money(x.n)).join('，'))}">${series.map(x=>`<div class="bar-col"><span class="bar-value sensitive">${money(x.n).slice(3)}</span><div class="bar" style="height:${Math.max(1,x.n/max*155)}px"></div><span class="bar-label">${Number(x.m.slice(-2))}月</span></div>`).join('')}</div><div class="legend">${I('leaf')} 每月支出扣除當月退款；負值以零高度顯示</div></div><div class="card"><div class="card-heading"><h2>分類支出</h2><small>淨支出占比</small></div>${categoryBars(s)}</div><div class="card" style="grid-column:1/-1"><div class="card-heading"><h2>給自己的小觀察</h2></div><p class="help">${s.expense>s.budget?`本月支出已超過預算 ${money(s.expense-s.budget)}，可以先看看金額最高的分類，找一個容易調整的小地方。`:s.expense>0?`本月預算還有 ${money(s.budget-s.expense)}。支出最多的是「${E(Object.entries(s.categories).sort((a,b)=>b[1]-a[1])[0][0])}」，下次消費前可以多留意一下。`:'先記錄幾筆花費，這裡會依實際帳目整理觀察。'}</p><small class="metric-note">以上依帳目規則計算，非 AI 生成；完整月份與未結束月份比較時，請留意天數差異。</small></div></div>`}
function creditPanel(a){const v=creditStatus(state,a.id);if(!v)return `<div class="metric-value">${amountHTML(balance(state,a.id))}</div>`;return `<div class="card-label">${isLinked(a)?'來源帳戶':''}帳本可用額度</div><div class="metric-value sensitive">${v.remaining===null?'尚未設定':money(v.remaining)}</div><div class="credit-breakdown"><div><small>總額度</small><strong class="sensitive">${v.limit===null?'未設定':money(v.limit)}</strong></div><div><small>已使用／未繳</small><strong class="sensitive">${money(v.used)}</strong></div></div>${v.overpaid?`<p class="help">溢繳款 <span class="sensitive">${money(v.overpaid)}</span>，暫不增加可用額度估算。</p>`:''}${v.overLimit?`<p class="help overspent">帳本已超出額度 <span class="sensitive">${money(v.overLimit)}</span>，請核對業者資料。</p>`:''}`}
function accountAmount(a){const v=creditStatus(state,a.id);return v?`<span>${v.remaining===null?'額度未設定':money(v.remaining)}</span><small class="tx-meta" style="display:block">可用額度 · 已用 ${money(v.used)}</small>`:money(balance(state,a.id))}
function accounts(){const total=totalBalance(state);return heading('每個帳戶，都心裡有數。','現金、銀行、信用卡、行動支付與先買後付，一起好管理。',`<button class="primary" id="add-account">${I('plus')}新增帳戶</button>`)+`<div class="card" style="margin-bottom:24px"><div class="card-label">帳戶淨額 <span class="pill">包含所有日期的紀錄</span></div><div class="metric-value">${amountHTML(total)}</div><p class="help">現金、存款與應收款，扣除信用卡及先買後付的未繳款。信用額度不列入資產或可花現金，綁定支付也不重複加總。應收代墊款仍待收回。此為手動帳本，未連接銀行或支付平台。</p></div><div class="account-grid">${state.accounts.map(a=>`<div class="card account-tile"><div class="card-heading"><span class="metric-icon">${I(accountIcon(a))}</span><button class="text-btn" data-account-edit="${E(a.id)}">編輯 ${I('edit')}</button></div><div class="card-label">${E(a.name)}</div>${creditPanel(a)}<p>${a.kind==='bnpl'?'先買後付／無卡分期 · 額度不屬於資產，還款用轉帳':a.kind==='card'?'信用卡 · 消費占用額度，還款恢復額度':a.kind==='bank'?'銀行帳戶':a.kind==='receivable'?'應收代墊款 · 尚未收回，不列為可花現金':a.kind==='mobile'?(isLinked(a)?'行動支付 · 綁定 '+E(accountName(a.linkedAccount))+'（顯示來源餘額，不重複加總）':'行動支付 · 獨立儲值餘額'):'現金錢包'}</p>${a.kind==='bnpl'?`<div class="bnpl-summary sensitive">${balance(state,a.id)<0?'待還款 '+money(-balance(state,a.id)):balance(state,a.id)>0?'溢繳款 '+money(balance(state,a.id)):'目前已結清'}</div><button class="secondary full" data-repay="${E(a.id)}" ${balance(state,a.id)>=0?'disabled':''}>${I('refresh')}記錄還款</button>`:''}</div>`).join('')}</div><div class="notice" style="margin-top:24px">信用卡與先買後付顯示的是依帳本推算的可用額度；業者待授權、保留款、共用額度及溢繳可用規則可能不同，以業者顯示為準。<br>繳信用卡或先買後付帳款請用「轉帳」，從銀行／現金轉入對應帳戶，避免把同一筆消費算兩次。手續費或利息請依實際帳單另記支出，分類選「手續費／利息」。退款請選「退款」，會回補帳戶並扣減原分類的支出。儲值錢包請用「轉帳」加值；綁卡型支付直接選行動支付帳戶記消費，系統會歸入綁定卡片，無須再記一次刷卡。</div>`}
function settings(){return installUI.panel()+daily.settingsPanel()+cloud.panel()+settingsBase()+advanced.backupPanel()}
function settingsBase(){return heading('你的帳本，你的習慣。','把工具調整成自己喜歡的樣子。')+`<div class="settings-grid"><div class="card"><div class="card-heading"><h2>${I('spark')} AI 小幫手</h2><span class="pill">${apiKey?'已連接':'可選用'}</span></div><div class="notice">不填金鑰也能使用文字規則解析。啟用 Gemini 後可理解較複雜的句子、辨識收據與付款截圖，結果一律由你確認後入帳。</div><form id="ai-settings"><label class="field" style="margin-top:20px">Gemini API Key<input type="password" id="api-key" autocomplete="off" spellcheck="false" placeholder="${keySaved?'此裝置已記住；留空沿用':'貼上自己的 API Key'}" value=""></label>${modelControls()}<label class="check"><input type="checkbox" id="remember-ai-key" ${keyPersistenceAvailable?'':'disabled'} ${rememberKey?'checked':''}><span>${keyPersistenceAvailable?'記住在此裝置：重開網頁自動載入。':'目前連線不支援保存金鑰，請在正式 HTTPS 網址啟用。'}${keySaved?'（目前已保存）':''}</span></label><label class="check"><input type="checkbox" id="free-confirm" required ${apiKey?'checked':''}><span>我使用未啟用付費帳單的免費專案。送出辨識時，僅將這次輸入的文字／圖片傳給 Google；免費服務的資料可能用於改善產品。</span></label><div class="row"><button class="primary" type="submit" ${modelLoading?'disabled':''}>${I('refresh')}${modelLoading?'正在讀取模型…':'啟用並讀取模型'}</button><button class="secondary" type="button" id="clear-key">清除金鑰</button></div><div class="inline-error" id="ai-setting-error" role="alert">${E(modelError)}</div></form><p class="help">免費額度由 Google 決定，可能因地區、模型與帳號調整。啟用自動切換後，遇到額度不足、模型下架或暫時忙碌，會在本次候選模型中依序嘗試；每次最多5個模型、總時間最多75秒。此工具無法判斷你的 Google 專案是否開啟計費，請確認使用免費專案。</p><p class="help">啟用「記住在此裝置」後，金鑰以裝置內加密方式保存在此瀏覽器，重開可繼續使用。它不會寫進帳本、匯出備份、雲端同步或 GitHub。共用裝置請取消記住或清除金鑰；同來源程式仍可使用已保存的金鑰。更換網址、瀏覽器或清除網站資料後需重新設定。</p><div class="row" style="flex-wrap:wrap"><a href="https://aistudio.google.com/apikey" target="_blank" rel="noopener noreferrer">取得免費專案金鑰 ↗</a><a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noopener noreferrer">查看官方額度與資料政策 ↗</a></div></div><div class="left-col"><div class="card"><div class="card-heading"><h2>${I('shield')} 資料與備份</h2><span class="pill">本機優先</span></div><p class="help">帳目先儲存在此瀏覽器；啟用上方雲端同步後，同帳號可跨裝置使用。清除網站資料前，請確認同步狀態並下載備份。舊網站帳目請先匯出，再於本站登入後還原。</p><div class="row" style="flex-wrap:wrap"><button class="secondary" id="export-json">${I('download')}下載完整備份</button><button class="secondary" id="import-json">${I('upload')}還原備份</button><button class="secondary" id="export-csv">${I('download')}匯出 CSV</button></div><input type="file" id="backup-file" accept="application/json,.json" hidden><p class="help">JSON 可完整還原；CSV 適合用 Excel 檢視。備份不含 AI 金鑰。${demo?'目前處於示範模式，匯出的也是示範資料。':''}</p>${corrupt?'<button class="secondary danger" id="raw-backup">下載無法讀取的原始資料</button>':''}</div><div class="card"><div class="card-heading"><h2>預算與使用偏好</h2></div><form id="default-budget-form"><label class="field">新月份的預設預算（NT$）<input type="number" step="0.01" min="0" max="10000000000" required id="default-budget" value="${state.defaultBudget/100}"></label><button class="secondary">儲存預設預算</button></form><p class="help">已單獨設定的月份預算會保留，可在總覽的「調整」修改。</p></div><div class="card"><div class="card-heading"><h2>先逛逛，再開始</h2></div><p class="help">示範帳本與你的實際帳目完全分開，隨時可返回。</p><button class="secondary" id="try-demo">${I('play')}${demo?'重新載入示範帳本':'開啟示範帳本'}</button><p class="help">手機可使用瀏覽器的「加入主畫面」。離線功能需先成功載入並由瀏覽器完成快取；AI 與部分語音辨識需要網路。</p></div></div></div>`}
function bind(){ installUI.bind();daily.bind();investments.bind();advanced.bind();cloud?.bind();invoices?.bind();settlements?.bind();$$('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo(0,0)});$$('[data-new]').forEach(b=>b.onclick=()=>openEntry());$$('[data-edit]').forEach(b=>b.onclick=()=>openEntry(state.transactions.find(t=>t.id===b.dataset.edit)));$$('[data-quick]').forEach(b=>b.onclick=()=>openEntry(null,{note:b.dataset.quick,category:b.dataset.cat}));$('#privacy').onclick=()=>{privateMode=!privateMode;render()};$('#month')?.addEventListener('change',e=>{if(e.target.value){month=e.target.value;render()}});$$('[data-month]').forEach(b=>b.onclick=()=>{const d=new Date(month+'-15T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(b.dataset.month));month=d.toISOString().slice(0,7);render()});$('#exit-demo')?.addEventListener('click',()=>{demo=false;state=real;month=today().slice(0,7);render();toast('已回到你的實際帳本')});$('#try-demo')?.addEventListener('click',()=>{demo=true;state=advancedDemo();month=today().slice(0,7);page='home';render();window.scrollTo(0,0)});$('#edit-budget')?.addEventListener('click',()=>budgetSheet());$('#quick-ai')?.addEventListener('submit',e=>{e.preventDefault();const text=$('#quick-text').value;openAI('text',text);if(text.trim())parseInput()});$('#home-photo')?.addEventListener('click',()=>openAI('photo'));$('#home-mic')?.addEventListener('click',()=>{openAI();startVoice()});$('#search')?.addEventListener('input',e=>{filters.q=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)});$('#filter-type')?.addEventListener('change',e=>{filters.type=e.target.value;render()});$('#filter-account')?.addEventListener('change',e=>{filters.account=e.target.value;render()});$('#add-account')?.addEventListener('click',()=>accountSheet());$$('[data-repay]').forEach(b=>b.onclick=()=>{const a=state.accounts.find(a=>a.id===b.dataset.repay);if(advanced.repayAccount(a.id))return;openEntry(null,{type:'transfer',account:(state.accounts.find(a=>a.kind==='bank')||state.accounts.find(a=>a.kind==='cash')||state.accounts[0]).id,toAccount:a.id,amount:Math.max(0,-balance(state,a.id)),note:a.name+' 還款'})});$$('[data-account-edit]').forEach(b=>b.onclick=()=>accountSheet(state.accounts.find(a=>a.id===b.dataset.accountEdit)));$('#export-json')?.addEventListener('click',()=>download(JSON.stringify(state,null,2),'日常有餘_備份_'+today()+'.json','application/json'));$('#export-csv')?.addEventListener('click',()=>download(csv(state),'日常有餘_全部紀錄_'+today()+'.csv','text/csv;charset=utf-8'));$('#import-json')?.addEventListener('click',()=>$('#backup-file').click());$('#backup-file')?.addEventListener('change',restore);$('#raw-backup')?.addEventListener('click',()=>{try{download(localStorage.getItem(KEY)||'','日常有餘_原始資料.txt','text/plain')}catch{toast('瀏覽器拒絕讀取儲存空間')}});bindAISettings();$('#default-budget-form')?.addEventListener('submit',e=>{e.preventDefault();try{const n=cents($('#default-budget').value);if(n<0)throw Error('預算不可為負數');if(commit({...state,defaultBudget:n})){render();toast('已儲存預設預算')}}catch(err){toast(err.message)}})}
function openSheet(title,html){aiRequest?.abort();aiGeneration++;stopVoice();$('#sheet').innerHTML=`<div class="sheet-header"><h2>${E(title)}</h2><button class="icon-btn" id="close-sheet" aria-label="關閉視窗">${I('close')}</button></div><div class="sheet-body">${html}</div>`;$('#close-sheet').onclick=()=>$('#sheet').close();if(!$('#sheet').open)$('#sheet').showModal();}
function defaultEntry(){return {id:uid(),bookId:activeBook==='all'?'personal':activeBook,tags:[],type:'expense',amount:0,note:'',category:'餐飲',account:state.accounts[0].id,toAccount:state.accounts[1]?.id,date:today()}}
function openEntry(existing=null,preset={}){if(existing?.origin&&existing.origin.kind!=='bill'){toast('此紀錄與管理項目關聯，請到對應管理頁修改');page=existing.origin.kind.startsWith('advance')?'settlements':existing.origin.kind==='reconcile'?'reconcile':'plans';$('#sheet').close();render();return}aiBusy=false;entry={...defaultEntry(),...existing,...preset};entry._editing=!!existing;entryMode='manual';manualSheet()}
function optionsAccounts(selected){return state.accounts.filter(a=>a.kind!=='receivable').map(a=>`<option value="${E(a.id)}" ${selected===a.id?'selected':''}>${E(a.name)}</option>`).join('')}
function manualSheet(){openSheet(entry._editing?'編輯紀錄':'記下一筆日常',`<div class="tabs"><button class="active" type="button">${I('edit')} 手動記帳</button><button id="switch-ai" type="button">${I('spark')} 智慧輸入</button></div><form id="entry-form"><div class="tabs" style="margin-bottom:15px">${Object.entries(TYPE_LABEL).map(([v,l])=>`<button type="button" data-type="${v}" class="${entry.type===v?'active':''}">${l}</button>`).join('')}</div><div class="amount-field"><label for="entry-amount">${TYPE_LABEL[entry.type]}金額</label><span>NT$</span><input id="entry-amount" type="number" step="0.01" inputmode="decimal" min="0.01" max="10000000000" placeholder="0" required value="${entry.amount?entry.amount/100:''}" autofocus></div><label class="field">項目名稱<input id="entry-note" maxlength="200" placeholder="這筆花在哪裡？" required value="${E(entry.note)}"></label>${entry.type==='transfer'?'':'<span class="form-label">分類</span><div class="category-picker">'+categoryList(state).map(c=>`<button type="button" data-category="${E(c)}" class="${entry.category===c?'active':''}">${E(c)}</button>`).join('')+'</div>'}<div class="row"><label class="field">${entry.type==='transfer'?'轉出帳戶':'使用帳戶'}<select id="entry-account">${optionsAccounts(entry.account)}</select></label><label class="field">日期<input type="date" required id="entry-date" value="${entry.date}"></label></div>${entry.type==='transfer'?`<label class="field">轉入帳戶<select id="entry-to">${optionsAccounts(entry.toAccount)}</select></label><div class="notice" style="margin-bottom:18px">轉帳不影響收支。繳卡費／先買後付帳款，請從實際付款帳戶轉入對應待還帳戶；可修改為這次實繳金額。若付款包含已建立的分期，請從「分期管理」記錄，才能同步每期進度。</div>`:''}${advanced.entryFields(entry)}${daily.entryExtras(entry)}<div id="entry-error" class="inline-error" role="alert"></div><button type="submit" class="primary full">${I('check')}儲存${entry._editing?'修改':'紀錄'}</button>${['expense','income'].includes(entry.type)?'<button type="button" class="secondary full" id="save-entry-template" style="margin-top:10px">存成常用範本（不入帳）</button>':''}${entry._editing?`<button type="button" class="secondary danger full" id="delete-entry" style="margin-top:10px">${I('trash')}刪除這筆紀錄</button>`:''}<div class="save-note">${demo?'示範模式 · 不影響實際帳目':'僅儲存在此瀏覽器 · 不會上傳你的帳本'}</div></form>`);$('#switch-ai').onclick=()=>{if(entry._editing){toast('編輯既有紀錄時請使用手動輸入');return}openAI()};$$('[data-type]').forEach(b=>b.onclick=()=>{captureEntry();entry.type=b.dataset.type;if(!entry.note&&entry.type==='transfer')entry.note='帳戶轉帳';manualSheet()});$$('[data-category]').forEach(b=>b.onclick=()=>{entry.category=b.dataset.category;$$('[data-category]').forEach(x=>x.classList.toggle('active',x===b))});daily.bindEntry(entry);$('#save-entry-template')?.addEventListener('click',()=>{captureEntry();daily.saveEntryTemplate(entry)});$('#entry-form').onsubmit=saveEntry;$('#delete-entry')?.addEventListener('click',()=>{if(confirm('刪除「'+entry.note+'」？可從設定的刪除復原取回。')){if(commit(trashTransaction(state,entry.id))){$('#sheet').close();render();toast('已刪除紀錄')}}})}
function captureEntry(){advanced.captureEntryMeta(entry);entry.note=$('#entry-note')?.value.trim()??entry.note;try{entry.amount=cents($('#entry-amount')?.value||0)}catch{}entry.account=$('#entry-account')?.value||entry.account;entry.toAccount=$('#entry-to')?.value||entry.toAccount;entry.date=$('#entry-date')?.value||entry.date}
function isDuplicate(t,ignore){return state.transactions.some(x=>x.id!==ignore&&x.amount===t.amount&&x.account===t.account&&x.type===t.type&&x.date===t.date&&x.note===t.note)}
function saveEntry(e){e.preventDefault();try{captureEntry();validateTx(entry,state);if(isDuplicate(entry,entry.id)&&!confirm('已有相同日期、金額與項目的紀錄，仍要儲存嗎？'))return;const {_editing,_fromTemplate,...tx}=entry;tx.toAccount=tx.type==='transfer'?tx.toAccount:null;const transactions=_editing?state.transactions.map(x=>x.id===tx.id?tx:x):[tx,...state.transactions];if(commit(daily.withLearnedRule({...state,transactions},tx))){$('#sheet').close();render();toast(_editing?'紀錄已更新':'已記下這筆日常')}}catch(err){$('#entry-error').textContent=err.message}}
function budgetSheet(){const n=summary(state,month).budget;openSheet('調整本月預算',`<p class="help">${month.replace('-','年')}月 · 可隨時調整</p><form id="budget-form"><label class="field">每月可花的預算（NT$）<input type="number" step="0.01" min="0" max="10000000000" id="budget-value" required value="${n/100}"></label><div class="inline-error" id="budget-error"></div><button class="primary full">儲存預算</button></form>`);$('#budget-form').onsubmit=e=>{e.preventDefault();try{const n=cents($('#budget-value').value);if(n<0)throw Error('預算不可為負數');if(commit(activeBook==='all'?{...state,budgets:{...state.budgets,[month]:n}}:{...state,features:{...state.features,bookBudgets:{...state.features.bookBudgets,[activeBook+':'+month]:n}}})){$('#sheet').close();render();toast('本月預算已更新')}}catch(err){$('#budget-error').textContent=err.message}}}
function accountSheet(a=null){
 if(a?.kind==='receivable'){page='settlements';render();toast('應收代墊款請由代墊／分帳頁管理');return;}
 const credit=a&&['card','bnpl'].includes(a.kind)?creditStatus(state,a.id):null;
 openSheet(a?'編輯帳戶':'新增帳戶',`<form id="account-form"><label class="field">帳戶名稱<input id="account-name" maxlength="40" required placeholder="例如：信用卡、AFTEE、悠遊付" value="${E(a?.name||'')}"></label><label class="field">帳戶類型<select id="account-kind">${[['cash','現金'],['bank','銀行帳戶'],['card','信用卡'],['mobile','行動支付'],['bnpl','先買後付／無卡分期']].map(([v,l])=>`<option value="${v}" ${a?.kind===v?'selected':''}>${l}</option>`).join('')}</select></label><div id="bnpl-fields"><span class="form-label">快速填入帳戶名稱</span><div class="quick-pills"><button type="button" data-bnpl-name="AFTEE">AFTEE</button><button type="button" data-bnpl-name="Pi 拍錢包慢點付">Pi 拍錢包慢點付</button></div><p class="help">消費先占用額度，分次還款會恢復額度。分期期數與費用可到「分期管理」設定。</p></div><div id="mobile-fields"><label class="field">行動支付付款方式<select id="payment-mode"><option value="balance" ${!isLinked(a||{})?'selected':''}>儲值錢包（有自己的餘額）</option><option value="linked" ${a&&isLinked(a)?'selected':''}>綁定銀行／信用卡／先買後付</option></select></label><label class="field" id="linked-field">扣款來源<select id="linked-account">${state.accounts.filter(x=>['bank','card','bnpl'].includes(x.kind)&&x.id!==a?.id).map(x=>`<option value="${E(x.id)}" ${a?.linkedAccount===x.id?'selected':''}>${E(x.name)}</option>`).join('')}</select></label></div><label class="field" id="opening-field">期初餘額（NT$）<input type="number" step="0.01" min="-10000000000" max="10000000000" id="account-opening" value="${(a?.opening||0)/100}"></label><div id="credit-fields"><label class="field">總額度（NT$，未知可留空）<input type="number" inputmode="decimal" step="0.01" min="0" max="10000000000" id="account-limit" value="${credit?.limit==null?'':credit.limit/100}" placeholder="例如：100000"></label><label class="field">目前已使用額度／未繳款（NT$）<input type="number" inputmode="decimal" step="0.01" min="0" max="10000000000" id="account-used" value="${(credit?.used||0)/100}"></label><label class="field">溢繳款（NT$，沒有請填0）<input type="number" inputmode="decimal" step="0.01" min="0" max="10000000000" id="account-overpaid" value="${(credit?.overpaid||0)/100}"></label><div class="notice" id="credit-preview" role="status"></div></div><p class="help" id="account-notice"></p><div class="inline-error" id="account-error" role="alert"></div><button class="primary full" style="margin-top:18px">儲存帳戶</button></form>`);
 const update=()=>{const kind=$('#account-kind').value,debt=['card','bnpl'].includes(kind),mobile=kind==='mobile',linked=mobile&&$('#payment-mode').value==='linked';$('#bnpl-fields').hidden=kind!=='bnpl';$('#mobile-fields').hidden=!mobile;$('#linked-field').hidden=!linked;$('#opening-field').hidden=linked||debt;$('#account-opening').disabled=linked||debt;$('#account-opening').required=!linked&&!debt;$('#credit-fields').hidden=!debt;for(const id of ['account-limit','account-used','account-overpaid'])$('#'+id).disabled=!debt;$('#account-used').required=debt;$('#account-overpaid').required=debt;$('#account-notice').textContent=debt?'額度不是資產或費用。新增時填目前已使用額度；編輯時若調整已用金額，視為帳戶餘額校正，不新增收入或支出。既有消費、還款及分期紀錄會保留。可用額度為帳本估算，以業者資料為準。':linked?'此支付帳戶共用來源。每筆消費只記一次，不要再到綁定銀行或信用卡重記。':mobile?'儲值錢包有獨立餘額，加值請用轉帳，付款時才記支出。':'期初餘額是開始記帳前已持有的現金／存款，修改時不會產生收入。';try{const limit=$('#account-limit').value.trim(),used=cents($('#account-used').value||0);$('#credit-preview').textContent=limit?'帳本可用額度：'+money(Math.max(0,cents(limit)-used)):'填入總額度後，會顯示帳本可用額度。'}catch{$('#credit-preview').textContent='請輸入有效金額';}};
 $('#account-kind').onchange=update;$('#payment-mode').onchange=update;for(const id of ['account-limit','account-used','account-overpaid'])$('#'+id).addEventListener('input',update);$$('[data-bnpl-name]').forEach(b=>b.onclick=()=>{$('#account-name').value=b.dataset.bnplName});update();
 $('#account-form').onsubmit=e=>{e.preventDefault();try{const name=$('#account-name').value.trim();if(!name)throw Error('請填寫名稱');if(state.accounts.some(x=>x.name===name&&x.id!==a?.id))throw Error('已有相同名稱的帳戶');const kind=$('#account-kind').value,paymentMode=$('#payment-mode').value,debt=['card','bnpl'].includes(kind);const account={id:a?.id||uid(),name,kind,opening:debt?debtOpening(state,a?.id,{used:cents($('#account-used').value),overpaid:cents($('#account-overpaid').value)}):kind==='mobile'&&paymentMode==='linked'?0:cents($('#account-opening').value)};if(debt&&$('#account-limit').value.trim()!=='')account.creditLimit=cents($('#account-limit').value);if(kind==='mobile'){account.paymentMode=paymentMode;if(paymentMode==='linked')account.linkedAccount=$('#linked-account').value}const next=validateBackup({...state,accounts:a?state.accounts.map(x=>x.id===a.id?account:x):[...state.accounts,account]});if(a&&state.transactions.some(t=>t.account===a.id||t.toAccount===a.id)&&JSON.stringify([a.kind,a.paymentMode,a.linkedAccount])!==JSON.stringify([account.kind,account.paymentMode,account.linkedAccount])&&!confirm('更改帳戶類型或綁定來源會重新歸屬歷史紀錄與餘額，確定修改？'))return;if(commit(next)){$('#sheet').close();render();toast('帳戶已儲存')}}catch(err){$('#account-error').textContent=err.message}};
}

function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();daily?.onDownload(content).catch(e=>toast('備份已產生，但健康紀錄未更新：'+e.message));setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function restore(e){const targetKey=KEY;const f=e.target.files[0];if(!f)return;try{if(f.size>25*1024*1024)throw Error('備份超過25MB');const next=validateBackup(JSON.parse(await f.text()));if(KEY!==targetKey)throw Error('帳號已切換，請重新選擇備份');if(!confirm(`即將以備份中的 ${next.transactions.length} 筆紀錄取代${demo?'示範':'目前'}帳本。建議先下載目前備份。確定還原？`))return;const wasCorrupt=corrupt;if(!demo)corrupt=false;if(commit(next)){if(!demo)real=state;render();toast('備份已還原')}else corrupt=wasCorrupt}catch(err){toast('還原失敗：'+err.message)}finally{e.target.value=''}}
function openAI(mode='text',text=''){pendingImage=null;drafts=[];aiBusy=false;aiMode=mode;entryMode='ai';aiSheet(text)}
function aiSheet(text=''){openSheet('讓小幫手，記下日常',`<div class="tabs"><button id="switch-manual">${I('edit')} 手動記帳</button><button class="active">${I('spark')} 智慧輸入</button></div><div class="tabs"><button data-ai-mode="text" class="${aiMode==='text'?'active':''}">文字／語音</button><button data-ai-mode="photo" class="${aiMode==='photo'?'active':''}">收據／截圖</button></div>${aiMode==='text'?`<label class="field">今天花了什麼？<textarea id="ai-text" rows="3" maxlength="2000" placeholder="午餐150現金，咖啡120刷卡">${E(text)}</textarea></label><div class="quick-pills"><button id="voice-start">${I('mic')}語音輸入</button><button id="example-text">試試範例</button></div><p class="help">未連接 AI 時使用免費規則解析：每筆一個數字、以逗號分開，支援「昨天」；辨識不準時可在預覽修改。</p>`:`<label class="photo-drop" for="receipt-file">${I('camera')}<strong>選擇收據或付款截圖</strong><small>手機可選擇拍照 · JPG、PNG、WebP，最大10MB</small></label><input type="file" accept="image/jpeg,image/png,image/webp" id="receipt-file" hidden><div id="receipt-preview"></div><p class="help">圖片只用於本次辨識，不會存入帳本。電子發票掃描與財政部同步尚未提供。</p>`}<div class="notice ${apiKey?'':'warn'}">${apiKey?'已連接 Gemini。按下辨識會將本次文字／圖片傳送給 Google；請避開卡號與其他敏感資訊。':aiMode==='photo'?'照片辨識需要先在「設定」加入自己的免費專案 Gemini 金鑰。':'目前為免金鑰文字解析；進階 AI 與照片辨識可在設定啟用。'}${!apiKey?' <button class="text-btn" id="go-ai-settings">前往設定 →</button>':''}</div><p class="help" id="ai-route-status" role="status" aria-live="polite">${apiKey?E(lastModel?'上次成功：'+lastModel:'辨識時自動選擇可用模型'):''}</p><div class="inline-error" id="ai-error" role="alert"></div><button class="primary full" id="parse-input" style="margin-top:18px">${I('spark')}${aiMode==='photo'?'辨識圖片':'整理成記帳紀錄'}</button>${apiKey&&aiMode==='text'?'<button class="secondary full" id="parse-local" style="margin-top:10px">改用免金鑰文字解析</button>':''}<div id="draft-area"></div>`);$('#switch-manual').onclick=()=>openEntry();$$('[data-ai-mode]').forEach(b=>b.onclick=()=>{if(aiBusy)return;aiMode=b.dataset.aiMode;pendingImage=null;drafts=[];aiSheet($('#ai-text')?.value||'')});$('#parse-input').onclick=()=>parseInput();$('#parse-local')?.addEventListener('click',()=>parseInput({localOnly:true}));$('#example-text')?.addEventListener('click',()=>{$('#ai-text').value='午餐150現金，咖啡120刷卡';$('#ai-text').focus()});$('#voice-start')?.addEventListener('click',startVoice);$('#go-ai-settings')?.addEventListener('click',()=>{$('#sheet').close();page='settings';render()});$('#receipt-file')?.addEventListener('change',loadPhoto)}
async function loadPhoto(e){const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error('圖片超過10MB，請先縮小');if(!['image/jpeg','image/png','image/webp'].includes(f.type))throw Error('請選擇 JPG、PNG 或 WebP 圖片');const bitmap=await createImageBitmap(f);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const c=document.createElement('canvas');c.width=Math.round(bitmap.width*scale);c.height=Math.round(bitmap.height*scale);c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();pendingImage=c.toDataURL('image/jpeg',.85);$('#receipt-preview').innerHTML=`<img class="image-preview" alt="本次辨識圖片預覽" src="${pendingImage}">`;$('#ai-error').textContent=''}catch(err){pendingImage=null;$('#ai-error').textContent='圖片載入失敗：'+err.message}}
function stopVoice(){if(recognition){recognition.onend=null;recognition.stop();recognition=null}}
function startVoice(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('此瀏覽器未提供語音辨識，請使用鍵盤麥克風或輸入文字');return}if(recognition){stopVoice();$('#voice-start')?.classList.remove('mic-on');return}const r=new SR();recognition=r;r.lang='zh-TW';r.interimResults=false;r.continuous=false;$('#voice-start')?.classList.add('mic-on');r.onresult=e=>{const input=$('#ai-text');if(input)input.value+=(input.value?'，':'')+e.results[0][0].transcript;toast('語音已轉成文字，請確認後再解析')};r.onerror=e=>toast(e.error==='not-allowed'?'麥克風權限未開啟，可改用鍵盤麥克風':'語音辨識未完成，請重試或輸入文字');r.onend=()=>{recognition=null;$('#voice-start')?.classList.remove('mic-on')};try{r.start()}catch{recognition=null;toast('麥克風無法啟動')}}
async function parseInput({localOnly=false}={}){if(aiBusy)return;const button=$('#parse-input');if(!button)return;const requestGeneration=aiGeneration;aiRequest=new AbortController();stopVoice();$('#ai-error').textContent='';drafts=[];$('#draft-area').innerHTML='';try{const text=$('#ai-text')?.value.trim()||'';if(aiMode==='photo'&&!pendingImage)throw Error('請先選擇一張圖片');if(aiMode==='photo'&&!apiKey)throw Error('請先到設定啟用免費專案 Gemini 金鑰');if(aiMode==='text'&&!text)throw Error('請先輸入內容');aiBusy=true;button.disabled=true;button.textContent=apiKey&&!localOnly?'小幫手正在整理…':'正在解析文字…';const inputMode=aiMode;let result;if(apiKey&&!localOnly){if(!router)throw Error('請先在設定讀取模型清單');const routed=await router.run(text,pendingImage,{state,preferred:model,autoSwitch,signal:aiRequest.signal,onStatus:info=>{if(requestGeneration===aiGeneration&&$('#ai-route-status'))$('#ai-route-status').textContent=info.message}});if(requestGeneration!==aiGeneration||!$('#sheet').open)return;result=routed.transactions;lastModel=routed.model;if($('#ai-route-status'))$('#ai-route-status').textContent='本次使用：'+routed.model+(routed.attempts.length?' · 已自動切換 '+routed.attempts.length+' 次':'')}else{result=parseLocal(text,state);if($('#ai-route-status'))$('#ai-route-status').textContent='本次使用：免金鑰文字規則解析'}if(!$('#sheet').open||entryMode!=='ai'||aiMode!==inputMode||aiGeneration!==requestGeneration)return;if(!result.length)throw Error('沒有找到可記帳的項目，請補充金額與名稱');drafts=daily.classify(result.map(t=>({...t,bookId:activeBook==='all'?'personal':activeBook,tags:[]})));renderDrafts();toast('已整理 '+drafts.length+' 筆，請核對後入帳')}catch(err){if(aiGeneration===requestGeneration&&$('#ai-error'))$('#ai-error').textContent=err.message}finally{if(aiGeneration===requestGeneration)aiBusy=false;if(button.isConnected){button.disabled=false;button.innerHTML=I('spark')+(aiMode==='photo'?'重新辨識圖片':'重新整理紀錄')}}}

function renderDrafts(){if(!$('#draft-area'))return;$('#draft-area').innerHTML=`<div class="card-heading" style="margin-top:24px"><h2 style="font-size:14px">確認後，才會入帳</h2><small>${drafts.length}筆待確認</small></div><form id="draft-form">${drafts.map((t,i)=>`<div class="draft-card" data-draft="${i}"><div class="draft-title"><span>第 ${i+1} 筆 ${isDuplicate(t)?' · ⚠ 疑似重複':''}</span><button type="button" data-remove-draft="${i}" aria-label="移除第${i+1}筆">${I('close')}</button></div><p class="help ${t.uncertain?'overspent':''}">${E(t.reviewWarning||'請核對金額、日期與使用帳戶，確認後才會入帳。')}${t.dailyRule?' 已帶入商家分類：'+E(t.dailyRule):''}</p><label class="field">所屬帳本<select data-key="bookId">${state.features.books.map(b=>`<option value="${E(b.id)}" ${b.id===t.bookId?'selected':''}>${E(b.name)}</option>`).join('')}</select></label><div class="row"><label class="field">名稱<input data-key="note" maxlength="200" required value="${E(t.note)}"></label><label class="field">金額（NT$）<input data-key="amount" type="number" step="0.01" min="0.01" required value="${t.amount/100}"></label></div><div class="row"><label class="field">日期<input data-key="date" type="date" required value="${E(t.date)}"></label><label class="field">類型<select data-key="type">${Object.entries(TYPE_LABEL).filter(([v])=>v!=='transfer').map(([v,l])=>`<option value="${v}" ${t.type===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="row"><label class="field">分類<select data-key="category">${categoryList(state).map(c=>`<option ${c===t.category?'selected':''}>${E(c)}</option>`).join('')}</select></label><label class="field">帳戶<select data-key="account">${optionsAccounts(t.account)}</select></label></div></div>`).join('')}<div class="inline-error" id="draft-error" role="alert"></div>${drafts.length?`<button class="primary full">${I('check')}確認並儲存 ${drafts.length} 筆</button>`:'<p class="help">已移除全部待確認紀錄。</p>'}</form>`;$$('[data-remove-draft]').forEach(b=>b.onclick=()=>{captureDrafts();drafts.splice(Number(b.dataset.removeDraft),1);renderDrafts()});$('#draft-form').onsubmit=e=>{e.preventDefault();try{captureDrafts();drafts.forEach(t=>validateTx(t,state));const seen=new Set();const dup=drafts.some(t=>{const key=JSON.stringify([t.date,t.amount,t.account,t.type,t.note]);const exists=seen.has(key)||isDuplicate(t);seen.add(key);return exists});if(dup&&!confirm('待入帳內容中有疑似重複紀錄，確定仍要全部入帳？'))return;if(commit({...state,transactions:[...drafts,...state.transactions]})){const count=drafts.length;$('#sheet').close();drafts=[];pendingImage=null;render();toast('已成功記下 '+count+' 筆紀錄')}}catch(err){$('#draft-error').textContent=err.message}}}
function captureDrafts(){$$('[data-draft]').forEach(el=>{const t=drafts[Number(el.dataset.draft)];el.querySelectorAll('[data-key]').forEach(input=>{t[input.dataset.key]=input.dataset.key==='amount'?cents(input.value):input.value.trim()})})}
$('#sheet').addEventListener('close',()=>{aiRequest?.abort();aiGeneration++;stopVoice();pendingImage=null});window.addEventListener('online',render);window.addEventListener('offline',render);window.addEventListener('storage',e=>{if(e.key===KEY){try{const next=e.newValue?validateBackup(JSON.parse(e.newValue)):fresh();real=upgrade(next);if(!demo){state=real;render();toast('已同步同瀏覽器另一分頁的修改')}}catch{toast('另一分頁的資料格式無法讀取')}}});
investments=createInvestmentUI({E,I,toast,openSheet,getState:()=>state,getStorageKey:()=>KEY,commit,render,runAI:async(task,text,images,context,{signal,onStatus}={})=>{if(!apiKey||!router)throw Error('請先到偏好設定啟用自己的 AI Key');const source=router,generation=aiGeneration,accountScope=KEY,original=state;const result=await source.run(text,images,{state:context,task,preferred:model,autoSwitch,signal,onStatus});if(source!==router||generation!==aiGeneration||accountScope!==KEY)throw Error('金鑰或帳號已變更，請重新分析');if(task==='stockCoach'&&original!==state)throw Error('分析期間帳本已變更，請重新分析');lastModel=result.model;return task==='stockImage'?result.stockRows:result.stockCoach;}});
daily=createDailyUI({E,I,toast,openSheet,download,getState:()=>state,getBook:()=>activeBook,getMonth:()=>month,getStorageKey:()=>KEY,isDemo:()=>demo,isCorrupt:()=>corrupt,commit,render,openEntry,openAI:()=>openAI(),navigate:p=>{page=p;render();window.scrollTo(0,0)},scanInvoice:()=>{page='invoices';render();$('#invoice-scan')?.click()}});
advanced=createAdvancedUI({E,I,toast,openSheet,download,getState:()=>state,getBook:()=>activeBook,getMonth:()=>month,setMonth:m=>{month=m;render()},isDemo:()=>demo,commit,render,navigate:p=>{page=p;render();window.scrollTo(0,0)},setBook:id=>{activeBook=id;render()},editTransaction:id=>openEntry(state.transactions.find(t=>t.id===id))});
settlements=createSettlementUI({E,I,toast,openSheet,commit,render,getState:()=>state,getBook:()=>activeBook});
invoices=createInvoiceUI({E,I,toast,openSheet,download,commit,render,getState:()=>state,getMonth:()=>month,getBook:()=>activeBook,getStorageKey:()=>KEY,
 extractInvoicePhoto:async(image,{signal,onStatus})=>{if(!apiKey||!router)throw Error('請先到設定啟用自己的 AI Key');const source=router,generation=aiGeneration;const result=await source.run('',image,{state,task:'invoice',preferred:model,autoSwitch,signal,onStatus});if(source!==router||generation!==aiGeneration)throw Error('金鑰或帳號已變更，請重新辨識');lastModel=result.model;return result.invoice;}
});
cloud=createCloudUI({E,I,toast,download,isDemo:()=>demo,getRealState:()=>real,getStorageKey:()=>KEY,commit,render,
 applyCloudState:next=>{if(demo)return false;const old=state;try{const value=upgrade(validateBackup(next));state=value;if(!persist()){state=old;return false}advanced.onChange(structuredClone(value),'雲端同步');render();return true}catch{return false}},
 switchAccount:async(userId,project)=>{const nextKey=accountStorageKey(project,userId);if(nextKey===KEY)return;keyGeneration++;await advanced.beforeSwitch();investments.cancel();aiRequest?.abort();aiGeneration++;apiKey='';router=null;model='auto';lastModel='';modelLoading=false;modelError='';keySaved=false;stopVoice();$('#sheet').close();demo=false;KEY=nextKey;corrupt=false;storageOK=true;try{const raw=localStorage.getItem(KEY);real=upgrade(raw?validateBackup(JSON.parse(raw)):fresh())}catch{real=upgrade(fresh());corrupt=true}state=real;activeBook='personal';filters={q:'',type:'',account:''};await advanced.switchScope(KEY);render();restoreDeviceKey();}
});
render();advanced.init().catch(e=>toast(e.message));cloud.init();restoreDeviceKey();investments.init();if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').catch(()=>{/* App remains usable online. */})}

function modelControls(){const snap=router?.snapshot(),list=snap?.models||[];return `<label class="field">模型選擇<select id="ai-model"><option value="auto" ${model==='auto'?'selected':''}>自動選擇（優先輕量模型）</option>${list.map(m=>`<option value="${E(m.id)}" ${model===m.id?'selected':''}>${E(m.name)}${m.health?' · 冷卻中':''}</option>`).join('')}</select></label><label class="check"><input type="checkbox" id="auto-switch" ${autoSwitch?'checked':''}><span>模型額度不足、忙碌或不支援時，自動換下一個候選模型。</span></label><div class="row" style="flex-wrap:wrap;margin-bottom:12px"><button type="button" class="secondary" id="refresh-models" ${!apiKey||modelLoading?'disabled':''}>${I('refresh')}重新讀取模型清單</button>${snap?.loadedAt?`<small class="help">讀取時間 ${new Date(snap.loadedAt).toLocaleTimeString('zh-TW',{timeZone:'Asia/Taipei'})}</small>`:''}</div>${snap?.loadedAt?`<div class="model-list">${list.length?list.map(m=>`<div class="model-row"><div><strong>${E(m.name)}</strong><small>${E(m.id)} · 文字／圖片</small></div><span class="${m.health?'model-wait':'model-ready'}">${m.health?E(m.health.reason)+' · '+new Date(m.health.until).toLocaleTimeString('zh-TW',{timeZone:'Asia/Taipei'})+' 後再試':m.lastSuccess?'曾成功回應':'待實際辨識確認'}</span></div>`).join(''):'<p class="help">清單中沒有已確認免費且適合記帳的候選模型。</p>'}</div><p class="help">官方清單共 ${snap.total} 個，納入 ${list.length} 個免費方案候選。其餘模型未確認免費、重複版本或不適合此功能，未納入自動切換。免費方案資料確認日：${POLICY_DATE}。模型清單不提供剩餘額度；是否可用依實際回應判斷。</p>`:'<p class="help">啟用後會讀取官方支援清單，自動挑選適合文字與照片記帳的免費方案候選模型。</p>'}`}
function bindAISettings(){
 $('#ai-model')?.addEventListener('change',e=>{model=e.target.value;saveDeviceKey().catch(e=>toast(e.message));});$('#auto-switch')?.addEventListener('change',e=>{autoSwitch=e.target.checked;saveDeviceKey().catch(e=>toast(e.message));});
 $('#remember-ai-key')?.addEventListener('change',async e=>{rememberKey=e.target.checked;try{await saveDeviceKey();toast(rememberKey?(apiKey?'已記住此裝置，下次會自動載入':'啟用金鑰後會記住此裝置'):'已移除裝置保存，下次需重新輸入');}catch(err){toast(err.message);}});
 $('#ai-settings')?.addEventListener('submit',async e=>{e.preventDefault();if(modelLoading)return;const key=$('#api-key').value.trim()||apiKey;if(key.length<15){$('#ai-setting-error').textContent='請貼上有效的個人金鑰';return}rememberKey=$('#remember-ai-key').checked;if(key!==apiKey){aiRequest?.abort();aiGeneration++;apiKey=key;router=createModelRouter({apiKey});model='auto';lastModel=''}try{await saveDeviceKey();}catch(err){toast('本次仍可使用，但未能記住金鑰：'+err.message);}await refreshModels();});
 $('#refresh-models')?.addEventListener('click',async()=>{const typed=$('#api-key').value.trim();if(typed&&typed!==apiKey){$('#ai-setting-error').textContent='金鑰有修改，請按「啟用並讀取模型」套用';return}await refreshModels()});
 $('#clear-key')?.addEventListener('click',async()=>{aiRequest?.abort();aiGeneration++;keyGeneration++;apiKey='';router=null;model='auto';lastModel='';modelError='';modelLoading=false;const oldRemember=rememberKey;rememberKey=false;try{await saveDeviceKey();toast('已清除本次與此裝置保存的金鑰');}catch(err){toast('本次已停用，裝置清除失敗：'+err.message);}rememberKey=oldRemember;render();});
}
async function saveDeviceKey(){const scope=KEY,value=apiKey,remember=rememberKey,settings={model,autoSwitch};const action=keyQueue.catch(()=>{}).then(()=>remember&&value?keyVault.remember(scope,value,settings):keyVault.forget(scope));keyQueue=action;await action;if(KEY===scope)keySaved=!!(remember&&value);}
async function restoreDeviceKey(){if(!keyPersistenceAvailable)return;const scope=KEY,generation=++keyGeneration;try{await keyQueue.catch(()=>{});const saved=await keyVault.load(scope);if(KEY!==scope||generation!==keyGeneration)return;keySaved=!!saved;rememberKey=true;if(saved){apiKey=saved.apiKey;model=saved.settings?.model||'auto';autoSwitch=saved.settings?.autoSwitch!==false;router=createModelRouter({apiKey});render();if(navigator.onLine)await refreshModels();}}catch(err){if(KEY===scope&&generation===keyGeneration)toast(err.message);}}

async function refreshModels(){const active=router;if(!active||modelLoading)return;modelLoading=true;modelError='';render();try{const snap=await active.refresh({force:true});if(router!==active)return;if(model!=='auto'&&!snap.models.some(m=>m.id===model))model='auto';toast(snap.models.length?'已讀取 '+snap.models.length+' 個免費方案候選模型':'未找到符合免費與記帳條件的模型')}catch(e){if(router===active)modelError=e.message}finally{if(router===active){modelLoading=false;render()}}}

function advancedDemo(){let s=upgrade(demoState());const t=s.transactions.find(t=>t.note==='運動用品');if(t)s=createPlan(s,{name:'運動用品示範分期',account:'card',bookId:'personal',category:'購物',totalPrincipal:t.amount,totalFee:900,count:3,firstDue:addDays(today(),3),purchaseDate:t.date,source:'bank',existingTxId:t.id});s=saveBill(s,{name:'房租示範排程',type:'expense',amount:1000000,category:'居住',account:'bank',toAccount:null,bookId:'personal',start:addDays(today(),5),end:null,interval:'monthly',active:true});s=saveBill(s,{name:'薪資示範排程',type:'income',amount:5200000,category:'其他',account:'bank',toAccount:null,bookId:'personal',start:addDays(today(),15),end:null,interval:'monthly',active:true});return s}
